```c
#include <stdio.h>

// Sigmoid activation function
int sigmoid(int x) {
    return 1 / (1 + (1 << -x));
}

// RNN structure
typedef struct {
    int input_size;
    int hidden_size;
    int output_size;
    int weights_ih[10][10];
    int weights_ho[10][10];
    int hidden_state[10];
} RNN;

// Initialization of RNN structure
void init_rnn(RNN *rnn, int input_size, int hidden_size, int output_size) {
    rnn->input_size = input_size;
    rnn->hidden_size = hidden_size;
    rnn->output_size = output_size;

    for (int i = 0; i < hidden_size; i++) {
        rnn->hidden_state[i] = 0;
        for (int j = 0; j < input_size; j++) {
            rnn->weights_ih[i][j] = 1;
        }
        for (int j = 0; j < output_size; j++) {
            rnn->weights_ho[i][j] = 1;
        }
    }
}

// Forward pass through RNN
void forward(RNN *rnn, int input[], int output[]) {
    int new_hidden_state[10];

    for (int i = 0; i < rnn->hidden_size; i++) {
        int sum = 0;
        for (int j = 0; j < rnn->input_size; j++) {
            sum += input[j] * rnn->weights_ih[i][j];
        }
        new_hidden_state[i] = sigmoid(sum);
    }

    for (int i = 0; i < rnn->output_size; i++) {
        int sum = 0;
        for (int j = 0; j < rnn->hidden_size; j++) {
            sum += new_hidden_state[j] * rnn->weights_ho[i][j];
        }
        output[i] = sigmoid(sum);
    }

    for (int i = 0; i < rnn->hidden_size; i++) {
        rnn->hidden_state[i] = new_hidden_state[i];
    }
}

int main() {
    RNN rnn;
    init_rnn(&rnn, 3, 3, 2);

    int input[] = {1, 2, 3};
    int output[2];

    forward(&rnn, input, output);

    printf("Output: %d %d\n", output[0], output[1]);

    return 0;
