using SerialPort;

namespace USBSerialController
{
    class USBSerialController
    {
        private SerialPort _serialPort;
        private string _deviceName;
        private int _baudRate;

        public USBSerialController(string deviceName, int baudRate)
        {
            _deviceName = deviceName;
            _baudRate = baudRate;
        }

        public void Connect()
        {
            _serialPort = new SerialPort();
            _serialPort.PortName = _deviceName;
            _serialPort.BaudRate = _baudRate;
            _serialPort.Parity = Parity.None;
            _serialPort.DataBits = 8;
            _serialPort.StopBits = StopBits.One;
            _serialPort.Handshake = Handshake.None;
            _serialPort.ReadBufferSize = 1024;
            _serialPort.ReadTimeout = 1000;
            _serialPort.Open();

            // Wait for the device to be recognized by the system
            while (_serialPort.IsOpen())
            {
                if (_serialPort.PortName == "USB Serial Port (COM" + _serialPort.Ports[0].Description.Replace("\'", "").Replace(" ", "_"))
                {
                    break;
                }
                Thread.Sleep(1000);
            }
        }

        public void Disconnect()
        {
            _serialPort.Close();
        }
    }
}
