```go
func _process(delta):
    var vector_A = Vector2.new(1, 0)
    var vector_B = Vector2.new(0, 1)
    var dot_product = vector_A.dot(vector_B)
    var magnitude_A = Math.sqrt(vector_A.length_squared())
    var magnitude_B = Math.sqrt(vector_B.length_squared())
    var rotational_angle = Math.acos(dot_product / (magnitude_A * magnitude_B))
    print("The rotational angle between vectors A and B is: " + rotational_angle)
```
