```python
import random

class Hangman:
    def __init__(self, word, num_guesses):
        self.word = word
        self.num_guesses = num_guesses
        self.letters = set(word)
        self.used_letters = set()
        self.remaining_guesses = num_guesses

    def guess(self, letter):
        if letter in self.used_letters:
            print("Game over!")
            return False
        self.used_letters.add(letter)
        if letter in self.letters:
            self.remaining_guesses -= 1
        else:
            print("Invalid guess!")
            return False
        return True

    def print_guess_options(self):
        print("You have used the following letters:")
        for letter in self.used_letters:
            print(letter)

    def print_remaining_guesses(self):
        print("You have", self.remaining_guesses, "guesses left.")

    def print_game_over(self):
        print("Game over!")

    def play(self):
        while self.remaining_guesses > 0:
            self.print_remaining_guesses()
            self.print_guess_options()
            guess = input("Enter a guess: ")
            if self.guess(guess):
                self.print_guess_options()
            else:
                self.print_game_over()
                return
```

