import json
import re

def parse_data(data):
    lines = data.split('\n')
    result = []

    for line in lines:
        if line.strip() == "":
            continue

        if line.startswith('tuote') or line.startswith('Article'):
            product_lines = line[5:].strip().split(' ')
            product_data = {line[0:5]: ''}

            for pl in product_lines:
                code, name, quantity, price = pl.split(' ')
                product_data[code] = {'name': name, 'quantity': int(quantity), 'price': float(price)}
                if code.isdigit():
                    product_data[code]['ean_upc'] = re.search(r'EAN-13: (\d+)', price).group(1) or re.search(r'UPC: (\d+)', price).group(1)

            result.append(product_data)
        elif line.strip().isdigit():
            order_data = {line.strip(): ''}
            for i, number in enumerate(line.split('/')):
                if i % 2 == 0:
                    order_data[number] = {}
                else:
                    order_data[number]['quantity'] = int(order_data[number].get('quantity', 0)) + 1
                    order_data[number]['unit_price'] = float(order_data[number].get('unit_price', 0))

            result.append(order_data)

    return json.dumps(result, indent=2)

