```python
def NAME_2(text, pattern):
    # Initialize variables to store the start and end positions of the pattern in the text
    start = 0
    end = 0
    match = 0

    # Loop through the characters in the pattern
    for i in range(len(pattern)):
        # If the pattern character is the same as the text character, increment the match variable
        if pattern[i] == text[end]:
            match += 1
        # If the pattern character is a wildcard, search forward in the text for the next wildcard
        elif pattern[i] == '*':
            while pattern[i+1] == '*':
                i += 1
            match += 1
        # If the pattern character is a dash, search backward in the text for the previous wildcard
        elif pattern[i] == '-':
            while pattern[i-1] == '-':
                i -= 1
            match -= 1
        # If the pattern character is at the end of the pattern, the pattern has been found
        elif pattern[i] == ' ':
            break
        # If the pattern character is at the beginning of the pattern, the pattern has been found
        elif pattern[i] == '^':
            break

    # If the pattern is not found, return -1
    if match != len(pattern):
        return -1

    # Calculate the number of characters that the pattern is shifted to the right
    shift = 0
    if start > end:
        shift = (text.count('-', 0, end) - pattern.count('-', 0, pattern)) // 2
    elif start < end:
        shift = (text.count('-', end, len(text)) - pattern.count('-', 0, pattern)) // 2

    return start + shift, end + shift + match
