```python
from typing import List

def fibonacci(n: int) -> List[int]:
    memo = {}
    if n < 0:
        raise ValueError('Negative number is not allowed')
    elif n == 0:
        return [0]
    elif n == 1:
        return [1]
    else:
        if n not in memo:
            memo[n] = fibonacci(n-1) + fibonacci(n-2)
        return memo[n]
```

