import threading

def factorial(n):
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

def main():
    # Create two threads to compute the factorial of 5 using two different approaches
    thread1 = threading.Thread(target=heavy_calculation, args=(5,))
    thread2 = threading.Thread(target=light_calculation, args=(5,))

    # Start the threads
    thread1.start()
    thread2.start()

    # Wait for the user to press Enter
