    # Join the threads, i.e., wait for them to finish
    thread1.join()
    thread2.join()

def heavy_calculation(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def light_calculation(n):
    return factorial(n)

if __name__ == "__main__":
    main()
```
