        if self.checkCollision([self.body[0]]):
            return True
        else:
            self.canvas.delete(self.canvas.find_withtag("NAME_1")[-1])
            self.body.pop()
            self.draw()
            return False

    def grow(self):
        self.advance(self.direction)
        self.draw()

    def advance(self, direction):
