class GameBoard:
    def __init__(self, size=3):
        self.size = size
        self.board = np.full((size, size, size), '')

    def is_valid_move(self, move):
        x, y, z = move
        return (0 <= x < self.size and 0 <= y < self.size and 0 <= z < self.size
                and self.board[x, y, z] == '')

    def update_board(self, move, player):
