            int sumVal = val + nextVal + carry;

            // Check if the sum is greater than 9
            if (sumVal > 9) {
                // If it is, then we need to carry the overflow to the next digit
                carry = 1;
                sumVal = 0;
            } else {
                // Otherwise, we can just update the curr node with the sum
