class Solution:
    def maxScore(self, nums: List[int]) -> int:

        def gcd(a, b):
            if b == 0:
                return a
            return gcd(b, a % b)

        n = len(nums)
        scoring_table = [0] * (1 << n)

        for i in range(1 << n):
            if i & 1 == 1:
                k = 2
            else:
                k = 1

            for j in range(i, (1 << n) - k):
                a, b = 2 * j + 1, 2 * (i - j) + 1
                if a <= b:
                    continue
                g = gcd(a, b)
                c = (a / g) * (b / g)
                scoring_table[i] = max(scoring_table[i], c + 1)

        return scoring_table[0]
