from math import sqrt

class Snake:
    def __init__(self):
        self.segments = [(5, 5), (5, 6), (5, 7)]
        self.direction = (1, 0)
        self.growth = 0
        self.dead = False

    def move(self):
        headX, headY = self.segments[0]
        dirX, dirY = self.direction
        newHead = (headX + dirX, headY + dirY)
        if self.growth > 0:
            self.growth -= 1
        else:
            self.segments.pop()
        self.segments.insert(0, newHead)

    def collidesWith(self, obj):
        head = self.segments[0]
        return sqrt((head[0] - obj[0]) ** 2 + (head[1] - obj[1]) ** 2) < 1

    def collidesWithSelf(self):
        head = self.segments[0]
        for segment in self.segments[1:]:
            if head == segment:
                self.dead = True
                return True
        return False

    def grow(self, amount=1):
        self.growth += amount

    def reset(self):
        self.__init__()
```

This class defines a simple Snake object with basic functionality, including movement, collision detection with an object or itself, growth, and resetting the snake to its initial state. The move() method updates the snake's position, the collidesWith() method checks for collision with other objects, and the collidesWithSelf() method checks if the snake has collided with itself.

