```go
func sieveOfEratosthenes(n int) []int {
    var primes []int
    for i := 2; i <= n; i++ {
        if primes[i] {
            primes = append(primes[:i], primes[i:])
            for j := i; j*2 <= n; j++ {
                primes[i*2] = false
            }
        }
    }
    return primes
}

```

